   N("Performance analysis", "Find bottlenecks with the right tools and methods.", ["USE method", "CPU & memory profiling", "flame graphs"], [("Brendan Gregg: Linux performance", "https://www.brendangregg.com/linuxperf.html")], core="s5m5"),
